def main():
    import sys
    n, m = map(int, sys.stdin.read().strip().split())
    points = []
    for x in range(n + 1):
        for y in range(m + 1):
            if x + y > 0 and (x + y) % 2 == 1:
                points.append((x, y))
    print(len(points))
    for x, y in points:
